CREATE TABLE IF NOT EXISTS app_users (id UUID PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(10) NOT NULL CHECK(role IN ('USER','ADMIN')), verified BOOLEAN NOT NULL DEFAULT FALSE, blocked BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS auth_tokens (token_hash CHAR(64) PRIMARY KEY, user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, purpose VARCHAR(10) NOT NULL CHECK(purpose IN ('SESSION','VERIFY','RESET')), expires_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS auth_tokens_user_idx ON auth_tokens(user_id);
